import { area, areaAll, centroid, clip, edgeLengths, fit, halfPlane, polyLineDist, polySegDist, union, type Poly, type Pt } from './geometry'
import { accessOk, envelope, frontage, MIN_LEVEL_M2, type Envelope, type Site } from './envelope'
import {
  ACCESS_ROAD_M, ACCESS_ROAD_XXL_M, BONUS_CAP, BONUS_MULT, EIA_M2, EIA_UNITS, FIRE_ACCESS_M, FRONTAGE_M, HIGH_RISE_M,
  PARKING_M2_PER_SPACE, PARKING_UNIT_M2, REF, SCOPE_ZONE, STATION_M, USES, XL_M2, XXL_M2, roadSetback, sideSetback, zoneRef,
  type Assumptions, type Flags, type Ref, type Use, type Zone,
} from '../rules/bangkok'

export type Status = 'pass' | 'check' | 'fail'
export type FloorUse = 'lobby' | 'parking' | 'main'

export interface Floor {
  i: number
  base: number
  top: number
  polys: Poly[]
  area: number
  use: FloorUse
}

export interface Check {
  id: string
  name: string
  value: string
  limit: string
  status: Status
  ref: Ref
  note?: string
}

export interface Design {
  key: string
  name: string
  blurb: string
  regime: 'low' | 'high'
  floors: Floor[]
  gfa: number
  mainArea: number
  parkingArea: number
  net: number
  units: number
  spacesReq: number
  spacesProv: number
  height: number // incl. roof allowance
  cover: number
  open: number
  far: number
  footprint: Poly[]
  checks: Check[]
  limitedBy: string
  error?: string
}

export interface Ctx {
  site: Site
  zone: Zone
  use: Use
  a: Assumptions
  f: Flags
  stationM: number | null
}

export interface Result {
  plotArea: number
  farBase: number
  farEff: number
  maxGfa: number
  access: boolean
  envLow: Envelope
  envHigh: Envelope
  designs: Design[]
}

const sum = (xs: number[]) => xs.reduce((s, x) => s + x, 0)
const f0 = (v: number) => Math.round(v).toLocaleString('en-US')
const f1 = (v: number) => v.toLocaleString('en-US', { maximumFractionDigits: 1, minimumFractionDigits: 1 })
const f2 = (v: number) => v.toLocaleString('en-US', { maximumFractionDigits: 2, minimumFractionDigits: 2 })
const ok = (c: boolean): Status => (c ? 'pass' : 'fail')
const EPS = 1e-6

/** Split region into two pieces either side of a gap across its longest direction. */
const split = (region: Poly, dir: Pt, gap: number): Poly[] => {
  const c = centroid(region)
  const [ux, uy] = dir
  return [
    clip(region, halfPlane([c[0] + (ux * gap) / 2, c[1] + (uy * gap) / 2], [ux, uy])),
    clip(region, halfPlane([c[0] - (ux * gap) / 2, c[1] - (uy * gap) / 2], [-ux, -uy])),
  ].filter(p => p.length && area(p) >= MIN_LEVEL_M2)
}

const longestDir = (p: Poly): Pt => {
  const ls = edgeLengths(p)
  const i = ls.indexOf(Math.max(...ls))
  const [a, b] = [p[i], p[(i + 1) % p.length]]
  return [(b[0] - a[0]) / ls[i], (b[1] - a[1]) / ls[i]]
}

/** Width of the rectangle with the same area and perimeter: exact for slabs and squares, conservative for jagged shapes. */
export const plateWidth = (p: Poly) => {
  const A = area(p)
  const h = edgeLengths(p).reduce((a, b) => a + b, 0) / 2
  const d = h * h - 4 * A
  return d > 0 ? (h - Math.sqrt(d)) / 2 : Math.sqrt(A)
}
const buildable = (p: Poly, minW: number) => plateWidth(p) >= minW

type Mode = 'tower' | 'twin' | 'slab' | 'blocks'

const META: Record<Mode, [string, string]> = {
  tower: ['Tower on podium', 'Parking podium filling the allowed space, one slender tower set inside the height plane.'],
  twin: ['Twin towers', 'Shared podium, two towers 6 m apart: smaller floor plates, more corner units.'],
  slab: ['Low-rise slab', 'Under 23 m, so high-rise access rules do not apply. Full floor plates.'],
  blocks: ['Twin low-rise blocks', 'Two blocks under 23 m with a 6 m courtyard between them.'],
}

/** Build a stack: lobby, `p` parking floors, then main-use floors, inside `env`, capped at maxGfa. */
const stack = (ctx: Ctx, env: Envelope, mode: Mode, p: number, cover: number, maxGfa: number): Floor[] => {
  const L = env.levels
  if (L.length < 2) return []
  const podium = fit(L[0].poly, cover)
  if (!podium.length) return []
  const floors: Floor[] = []
  let g = 0
  const push = (i: number, polys: Poly[], use: FloorUse) => {
    const ps = polys.filter(x => x.length > 2 && area(x) >= MIN_LEVEL_M2 && buildable(x, ctx.a.minWidth))
    if (!ps.length) return false
    let a = areaAll(ps)
    if (g + a > maxGfa + EPS) {
      const left = maxGfa - g
      if (left < MIN_LEVEL_M2 * ps.length) return false
      const scaled = ps.map(x => fit(x, (area(x) * left) / a)).filter(x => x.length)
      if (!scaled.length) return false
      ps.splice(0, ps.length, ...scaled)
      a = areaAll(ps)
    }
    floors.push({ i, base: L[i].base, top: L[i].top, polys: ps, area: a, use })
    g += a
    return true
  }
  const towers = mode === 'tower' || mode === 'twin'
  const twin = mode === 'twin' || mode === 'blocks'
  const podLevels = towers ? Math.min(p + 1, L.length) : 1
  for (let i = 0; i < podLevels; i++) if (!push(i, [clip(podium, L[i].poly)], i === 0 ? 'lobby' : 'parking')) return floors
  if (podLevels >= L.length) return floors
  const region = clip(podium, L[podLevels].poly)
  const dir = longestDir(region.length ? region : podium)
  let plates: Poly[] = twin ? split(region, dir, FIRE_ACCESS_M) : [region]
  if (towers) {
    // plate grows on large plots so the tower stays within maxStoreys
    const target = Math.max(ctx.a.plate, (maxGfa - g) / Math.max(1, ctx.a.maxStoreys)) * (twin ? 0.6 : 1)
    plates = plates.map(x => fit(x, Number.isFinite(target) ? target : ctx.a.plate)).filter(x => x.length && buildable(x, ctx.a.minWidth))
  }
  if (!plates.length) return floors
  for (let i = podLevels; i < L.length; i++) {
    const use: FloorUse = !towers && i <= p ? 'parking' : 'main'
    if (!push(i, plates.map(x => clip(x, L[i].poly)), use)) break
  }
  return floors
}

const MAX_PARK = 14

const evalDesign = (ctx: Ctx, r: Omit<Result, 'designs'>, env: Envelope, mode: Mode): Design => {
  const { a, use } = ctx
  const spec = USES[use]
  const plotA = r.plotArea
  const reqOpenExtra = a.bonusOpen
  // MR 33 ข้อ 2: without a 10 m road stay under 10,000 m²; without an 18 m road stay under 30,000 m²
  const capG = !ctx.f.access ? r.maxGfa
    : !r.access ? Math.min(r.maxGfa, XL_M2 - 1)
    : ctx.site.width < ACCESS_ROAD_XXL_M ? Math.min(r.maxGfa, XXL_M2 - 1) : r.maxGfa
  let cover = Math.max(0, (plotA - reqOpenExtra) / (ctx.f.open ? 1 + spec.openShare : 1))
  let best: Floor[] = []
  const enough = (fl: Floor[]) => {
    const main = sum(fl.filter(f => f.use === 'main').map(f => f.area))
    const park = sum(fl.filter(f => f.use === 'parking').map(f => f.area))
    return !main || park / a.parkingSpace >= spacesRequired(ctx, main)
  }
  for (let iter = 0; iter < 4; iter++) {
    // first guess of parking floors from the GFA cap, then step to the smallest count that suffices
    const g0 = Math.min(capG, sum(env.levels.map(l => Math.min(l.area, cover))))
    let p = Math.max(0, Math.min(MAX_PARK, Math.ceil(((g0 / PARKING_M2_PER_SPACE) * a.parkingSpace) / Math.max(cover, 1)) - 1))
    let floors = stack(ctx, env, mode, p, cover, capG)
    if (enough(floors)) {
      while (p > 0) {
        const fewer = stack(ctx, env, mode, p - 1, cover, capG)
        if (!enough(fewer)) break
        p--
        floors = fewer
      }
    } else {
      while (p < MAX_PARK && !enough(floors)) floors = stack(ctx, env, mode, ++p, cover, capG)
    }
    best = floors
    if (!ctx.f.open) break
    const g = sum(floors.map(f => f.area))
    const largest = Math.max(0, ...floors.map(f => f.area))
    const need = Math.max((ctx.zone.osr / 100) * g, spec.openShare * largest) + reqOpenExtra
    const coverNow = floors.length ? floors[0].area : 0
    if (plotA - coverNow >= need - EPS) break
    cover = Math.max(0, plotA - need) * 0.995
  }
  return finish(ctx, r, env, mode, best, capG)
}

const spacesRequired = (ctx: Ctx, main: number) => {
  if (ctx.use !== 'condo') return Math.ceil(main / PARKING_M2_PER_SPACE)
  const units = ctx.a.unitSize > 0 ? Math.floor((main * ctx.a.efficiency) / ctx.a.unitSize) : 0
  return Math.max(ctx.a.unitSize >= PARKING_UNIT_M2 ? units : 0, Math.ceil(main / PARKING_M2_PER_SPACE))
}

const finish = (ctx: Ctx, r: Omit<Result, 'designs'>, env: Envelope, mode: Mode, floors: Floor[], capG: number): Design => {
  const { site, a, use, zone } = ctx
  const spec = USES[use]
  const [name, blurb] = META[mode]
  const plotA = r.plotArea
  const gfa = sum(floors.map(f => f.area))
  const mainArea = sum(floors.filter(f => f.use === 'main').map(f => f.area))
  const parkingArea = sum(floors.filter(f => f.use === 'parking').map(f => f.area))
  const net = mainArea * a.efficiency
  const units = spec.unitLabel && a.unitSize > 0 ? Math.floor(net / a.unitSize) : 0
  const spacesReq = spacesRequired(ctx, mainArea)
  const spacesProv = Math.floor(parkingArea / a.parkingSpace)
  const top = floors.at(-1)?.top ?? 0
  const height = floors.length ? top + a.roof : 0
  const footprint = union(floors.flatMap(f => f.polys))
  const cover = areaAll(footprint)
  const open = plotA - cover
  const largest = Math.max(0, ...floors.map(f => f.area))
  const high = height >= HIGH_RISE_M
  const xl = gfa >= XL_M2
  const roadIdx = site.road.map((x, i) => (x ? i : -1)).filter(i => i >= 0)
  const sideIdx = site.road.map((x, i) => (x ? -1 : i)).filter(i => i >= 0)
  const P = site.plot
  const seg = (i: number): [Pt, Pt] => [P[i], P[(i + 1) % P.length]]
  const polys = floors.flatMap(f => f.polys.map(poly => ({ poly, f })))

  const checks: Check[] = []
  const add = (c: Check) => checks.push(c)

  if (!floors.length) {
    return { key: mode, name, blurb, regime: env.regime, floors, gfa: 0, mainArea: 0, parkingArea: 0, net: 0, units: 0, spacesReq: 0, spacesProv: 0, height: 0, cover: 0, open: plotA, far: 0, footprint: [], checks, limitedBy: '', error: 'Nothing fits: the allowed space is too small for this design.' }
  }

  add({ id: 'far', name: 'Floor area ratio (FAR)', value: f2(gfa / plotA), limit: `≤ ${f2(r.farEff)}`, status: ok(gfa / plotA <= r.farEff + EPS), ref: zoneRef(zone, `FAR ${zone.far}:1`), note: r.farEff > r.farBase ? `Includes +${f2(r.farEff - r.farBase)} bonus (ข้อ 53).` : undefined })
  add({ id: 'osr', name: 'Open space ratio (OSR)', value: `${f1((open / gfa) * 100)}%`, limit: `≥ ${zone.osr}%`, status: ok(open / gfa >= zone.osr / 100 - EPS), ref: zoneRef(zone, `OSR ${zone.osr}%`), note: `Open space ${f0(open)} m² of total floor area ${f0(gfa)} m².` })
  add({ id: 'open', name: `Open space ≥ ${spec.openShare * 100}% of largest floor`, value: `${f0(open)} m²`, limit: `≥ ${f0(spec.openShare * largest + a.bonusOpen)} m²`, status: ok(open >= spec.openShare * largest + a.bonusOpen - EPS), ref: spec.openRef, note: a.bonusOpen ? 'Limit includes the public open space offered for the bonus.' : undefined })
  add({ id: 'planted', name: 'Planted, permeable open space', value: `${f0(open * 0.5)} m² to plant`, limit: '≥ 50% of open space', status: 'check', ref: REF.planted, note: 'Landscape design must show it; not drawn at concept stage.' })

  if (!roadIdx.length) {
    add({ id: 'roadside', name: 'Road frontage', value: 'none marked', limit: 'plot must face a public road', status: 'fail', ref: REF.road, note: 'Click a plot edge on the map to mark it as road frontage.' })
  } else {
    const reqRoad = roadSetback(site.width, height > 8 || floors.length > 2)
    const dRoad = Math.min(...polys.flatMap(({ poly }) => roadIdx.map(i => polyLineDist(poly, ...seg(i)))))
    add({ id: 'road', name: 'Setback from road boundary', value: `${f1(dRoad)} m`, limit: `≥ ${f1(reqRoad)} m`, status: ok(dRoad >= reqRoad - 0.05), ref: REF.road, note: `Road right-of-way ${f1(site.width)} m.` })
    let worst = { ex: -Infinity, h: 0, lim: 0 }
    for (const { poly, f } of polys) {
      const d = Math.min(...roadIdx.map(i => polyLineDist(poly, ...seg(i))))
      const h = f.top + (f === floors.at(-1) ? a.roof : 0)
      const lim = 2 * (site.width + d)
      if (h - lim > worst.ex) worst = { ex: h - lim, h, lim }
    }
    add({ id: 'plane', name: 'Height vs road width', value: `${f1(worst.h)} m`, limit: `≤ ${f1(worst.lim)} m at that point`, status: ok(worst.ex <= 0.05), ref: REF.plane, note: 'Worst floor: height against 2 × distance to the far side of the road.' })
  }

  const reqSide = sideSetback(height)
  if (sideIdx.length) {
    const dSide = Math.min(...polys.flatMap(({ poly }) => sideIdx.map(i => polySegDist(poly, ...seg(i)))))
    add({ id: 'side', name: 'Side and rear setbacks', value: `${f1(dSide)} m`, limit: `≥ ${f1(reqSide)} m`, status: ok(dSide >= reqSide - 0.05), ref: high ? REF.fire : REF.side, note: high ? REF.fire.note : undefined })
  }

  if (high || xl) {
    const need = gfa > XXL_M2 ? ACCESS_ROAD_XXL_M : ACCESS_ROAD_M
    const why = [high && `height ${f1(height)} m ≥ 23 m`, xl && `floor area ≥ 10,000 m²`].filter(Boolean).join(', ')
    add({ id: 'access', name: 'Road width for high-rise / extra-large', value: `${f1(site.width)} m`, limit: `≥ ${need} m`, status: ok(roadIdx.length > 0 && site.width >= need), ref: REF.access, note: `Applies because ${why}. Width must hold all the way to a road of the same width.` })
    add({ id: 'frontage', name: 'Frontage on that road', value: `${f1(frontage(site))} m`, limit: `≥ ${FRONTAGE_M} m`, status: ok(frontage(site) >= FRONTAGE_M), ref: REF.frontage })
  } else {
    add({ id: 'access', name: 'High-rise / extra-large rules', value: `${f1(height)} m, ${f0(gfa)} m²`, limit: '< 23 m and < 10,000 m²', status: 'pass', ref: REF.access, note: 'Not triggered.' })
  }

  if (zone.code === SCOPE_ZONE) {
    const trig = use === 'hotel' ? units > 80 : use === 'office' ? gfa > XL_M2 : false
    if (trig) {
      const near = ctx.stationM !== null && ctx.stationM <= STATION_M
      add({ id: 'use', name: `${spec.label} size condition`, value: `road ${f1(site.width)} m · station ${ctx.stationM === null ? 'unknown' : `${f0(ctx.stationM)} m`}`, limit: `road ≥ 12 m or station ≤ ${STATION_M} m`, status: ok(site.width >= 12 || near), ref: REF.useCond, note: use === 'hotel' ? 'Hotels over 80 rooms.' : 'Offices over 10,000 m².' })
    } else {
      add({ id: 'use', name: `${spec.label} permitted in ${zone.code}`, value: 'yes', limit: 'not in prohibited list', status: 'pass', ref: zoneRef(zone, 'permitted uses') })
    }
  } else {
    add({ id: 'use', name: `Use conditions in ${zone.code}`, value: 'not modelled', limit: '—', status: 'check', ref: zoneRef(zone, 'permitted uses'), note: `Only ${SCOPE_ZONE} use conditions are modelled.` })
  }

  add({ id: 'parking', name: 'Parking spaces', value: f0(spacesProv), limit: `≥ ${f0(spacesReq)}`, status: ok(spacesProv >= spacesReq), ref: use === 'condo' ? REF.parking : REF.parkingOther, note: `Parking floors ${f0(parkingArea)} m² at ${a.parkingSpace} m² per space (assumption).` })

  if (use === 'condo') {
    const eia = units >= EIA_UNITS || gfa >= EIA_M2
    add({ id: 'eia', name: 'Environmental impact assessment', value: `${f0(units)} units, ${f0(gfa)} m²`, limit: `< ${EIA_UNITS} units and < ${f0(EIA_M2)} m²`, status: eia ? 'check' : 'pass', ref: REF.eia, note: eia ? 'EIA report must be approved before construction.' : undefined })
  }

  return { key: mode, name, blurb, regime: env.regime, floors, gfa, mainArea, parkingArea, net, units, spacesReq, spacesProv, height, cover, open, far: gfa / plotA, footprint, checks, limitedBy: limit(r, env, gfa, capG, floors) }
}

const limit = (r: Omit<Result, 'designs'>, env: Envelope, gfa: number, capG: number, floors: Floor[]) => {
  if (gfa >= r.maxGfa - 1) return 'Reaches the FAR limit.'
  if (capG < r.maxGfa && gfa >= capG - 1)
    return capG < XL_M2 ? 'Capped below 10,000 m²: the road is under 10 m or the frontage under 12 m (MR 33 ข้อ 2).' : 'Capped below 30,000 m²: the road is under 18 m (MR 33 ข้อ 2).'
  if (env.regime === 'low') return 'Kept under 23 m so high-rise rules do not apply; the low-rise allowed space is full.'
  return `Stops at ${floors.length} floors: above that the height-vs-road plane, setbacks and minimum floor width leave no buildable plate.`
}

export const analyse = (ctx: Ctx): Result => {
  const { site, zone, a, f } = ctx
  const plotArea = area(site.plot)
  const farBase = zone.far
  const bonus = Math.min(BONUS_MULT * a.bonusOpen, BONUS_CAP * farBase * plotArea) / plotArea
  const farEff = farBase + bonus
  const maxGfa = f.far ? farEff * plotArea : Infinity
  const access = !f.access || accessOk(site)
  const envLow = envelope(site, a, f, 'low')
  const envHigh = envelope(site, a, f, 'high')
  const r = { plotArea, farBase, farEff, maxGfa, access, envLow, envHigh }
  const modes: [Mode, Envelope][] = access
    ? [['tower', envHigh], ['twin', envHigh], ['slab', envLow]]
    : [['slab', envLow], ['blocks', envLow], ['tower', envHigh]]
  return { ...r, designs: modes.map(([m, e]) => evalDesign(ctx, r, e, m)) }
}
---
import { area, edgeLengths, pointInPoly, type Poly, type Pt } from './geometry'
import { projector, type LL } from './project'
import { ROAD_CLASS_M, SRC, type Zone } from '../rules/bangkok'

export interface RawBuilding { id: number; g: LL[]; h?: string; l?: string; t?: string; n?: string }
export interface RawRoad { id: number; g: LL[]; k: string; w?: string; ln?: string; n?: string }
export interface Context { bbox: [number, number, number, number]; source: string; fetched: string; buildings: RawBuilding[]; roads: RawRoad[]; stations: { name: string; c: LL }[] }

export type HeightBasis = 'osm-height' | 'osm-levels' | 'estimated'

const num = (s?: string) => {
  const v = parseFloat((s ?? '').replace(',', '.'))
  return Number.isFinite(v) && v > 0 ? v : null
}

const LEVEL_M = 3.2 // assumption: storey height for OSM building:levels
/** Height of a context building and how it was obtained. Estimates are labelled in the UI. */
export const buildingHeight = (b: RawBuilding, footprintM2: number): [number, HeightBasis] => {
  const h = num(b.h)
  if (h) return [h, 'osm-height']
  const l = num(b.l)
  if (l) return [l * LEVEL_M, 'osm-levels']
  if (b.t === 'house' || b.t === 'terrace' || b.t === 'detached') return [7, 'estimated']
  return [footprintM2 < 150 ? 9 : footprintM2 < 600 ? 13 : 20, 'estimated']
}

const inBox = ([lng, lat]: LL, [w, s, e, n]: number[]) => lng >= w && lng <= e && lat >= s && lat <= n

/** Ids of context buildings standing on the plot (assumed to be cleared). */
export const onPlot = (ctx: Context | null, plot: LL[]): number[] => {
  if (!ctx || plot.length < 3) return []
  const pr = projector(plot[0])
  const plotM = plot.map(pr.toM)
  const [mx, Mx, my, My] = [Math.min(...plotM.map(p => p[0])), Math.max(...plotM.map(p => p[0])), Math.min(...plotM.map(p => p[1])), Math.max(...plotM.map(p => p[1]))]
  return ctx.buildings
    .filter(b => {
      const m = b.g.slice(0, -1).map(pr.toM)
      if (m.every(([x]) => x < mx) || m.every(([x]) => x > Mx) || m.every(([, y]) => y < my) || m.every(([, y]) => y > My)) return false
      return m.some(v => pointInPoly(v, plotM)) || plotM.some(v => pointInPoly(v, m))
    })
    .map(b => b.id)
}

export const contextGeoJSON = (ctx: Context | null, skip: Set<number>): GeoJSON.FeatureCollection => {
  if (!ctx?.buildings.length) return { type: 'FeatureCollection', features: [] }
  const pr = projector(ctx.buildings[0].g[0])
  return {
    type: 'FeatureCollection',
    features: ctx.buildings
      .filter(b => !skip.has(b.id) && b.g.length > 3)
      .map(b => {
        const [h, basis] = buildingHeight(b, area(b.g.slice(0, -1).map(pr.toM)))
        return { type: 'Feature', properties: { h, basis, n: b.n ?? '' }, geometry: { type: 'Polygon', coordinates: [b.g] } }
      }),
  }
}

export const roadWidthEstimate = (r: RawRoad): [number, string] => {
  const w = num(r.w)
  if (w) return [w, 'OSM width tag']
  return [ROAD_CLASS_M[r.k] ?? 8, `estimate from OSM road class “${r.k}”`]
}

export interface RoadGuess { road: boolean[]; width: number; basis: string; name: string }

/** Mark plot edges that run along a mapped road; take the widest such road (MR 55 ข้อ 46). */
export const detectRoad = (ctx: Context | null, plot: LL[]): RoadGuess => {
  const none: RoadGuess = { road: plot.map((_, i) => i === 0), width: 8, basis: 'no mapped road found nearby; edge 1 assumed', name: '' }
  if (!ctx) return none
  const pr = projector(plot[0])
  const P = plot.map(pr.toM)
  const lens = edgeLengths(P)
  const segs = ctx.roads.flatMap(r => {
    const g = r.g.map(pr.toM)
    if (!g.some(([x, y]) => Math.abs(x) < 400 && Math.abs(y) < 400)) return []
    const [w] = roadWidthEstimate(r)
    return g.slice(1).map((b, i) => ({ a: g[i], b, r, w }))
  })
  const best = P.map((a, i) => {
    const b = P[(i + 1) % P.length]
    const mid: Pt = [(a[0] + b[0]) / 2, (a[1] + b[1]) / 2]
    const [ux, uy] = [(b[0] - a[0]) / lens[i], (b[1] - a[1]) / lens[i]]
    let hit: (typeof segs)[number] | null = null
    let hd = Infinity
    for (const s of segs) {
      const [dx, dy] = [s.b[0] - s.a[0], s.b[1] - s.a[1]]
      const l = Math.hypot(dx, dy)
      if (l < 1e-6 || Math.abs((ux * dx + uy * dy) / l) < 0.85) continue
      const t = Math.max(0, Math.min(1, ((mid[0] - s.a[0]) * dx + (mid[1] - s.a[1]) * dy) / (l * l)))
      const d = Math.hypot(mid[0] - s.a[0] - t * dx, mid[1] - s.a[1] - t * dy)
      if (d <= s.w / 2 + 8 && d < hd) { hd = d; hit = s }
    }
    return hit
  })
  if (!best.some(Boolean)) return none
  const top = best.filter(Boolean).sort((a, b) => b!.w - a!.w)[0]!
  const [width, basis] = roadWidthEstimate(top.r)
  return { road: best.map(Boolean), width, basis, name: top.r.n ?? top.r.k }
}

export const nearestStation = (ctx: Context | null, at: LL): { name: string; m: number } | null => {
  if (!ctx?.stations.length) return null
  const pr = projector(at)
  return ctx.stations.map(s => ({ name: s.name, m: Math.hypot(...pr.toM(s.c)) })).sort((a, b) => a.m - b.m)[0]
}

const TH = '๐๑๒๓๔๕๖๗๘๙'
const thaiDigits = (s: string) => s.replace(/[๐-๙]/g, d => String(TH.indexOf(d)))
/** "ย.10-7" → "ย.10" */
const baseCode = (s: string) => thaiDigits(s).replace(/-\d+$/, '').trim()

export interface ZoneFC { features: { properties: { zone: string; far: number; osr: number; law?: string }; geometry: { type: string; coordinates: number[][][] | number[][][][] } }[] }

export const zoneAt = (fc: ZoneFC | null, at: LL): Zone | null => {
  if (!fc) return null
  const pr = projector(at)
  for (const f of fc.features) {
    const polys = (f.geometry.type === 'Polygon' ? [f.geometry.coordinates] : f.geometry.coordinates) as LL[][][]
    if (polys.some(p => pointInPoly([0, 0], p[0].map(pr.toM) as Poly))) {
      const p = f.properties
      return { code: baseCode(p.zone), sub: thaiDigits(p.zone), far: p.far, osr: p.osr, law: p.law }
    }
  }
  return null
}

/** Live lookup on the BMA layer for plots outside the bundled zone extract. */
export const fetchZone = async ([lng, lat]: LL): Promise<Zone | null> => {
  const u = `${SRC.plan}/query?geometry=${lng},${lat}&geometryType=esriGeometryPoint&inSR=4326&spatialRel=esriSpatialRelIntersects&outFields=LUP_ZONE,LUP_FAR,LUP_OSR,LAW_URL&returnGeometry=false&f=json`
  const j = await (await fetch(u)).json()
  const a = j.features?.[0]?.attributes
  return a ? { code: baseCode(a.LUP_ZONE), sub: thaiDigits(a.LUP_ZONE), far: a.LUP_FAR, osr: a.LUP_OSR, law: a.LAW_URL } : null
}

const OVERPASS = ['https://overpass-api.de/api/interpreter', 'https://overpass.private.coffee/api/interpreter', 'https://maps.mail.ru/osm/tools/overpass/api/interpreter']

/** Live OSM context around a point (used outside the bundled snapshot). */
const parse = (d: { osm3s?: { timestamp_osm_base?: string }; elements: { type: string; id: number; tags?: Record<string, string>; lon: number; lat: number; geometry: { lon: number; lat: number }[] }[] }, bbox: Context['bbox']): Context => {
  const ctx: Context = { bbox, source: 'OpenStreetMap contributors via Overpass API (ODbL)', fetched: d.osm3s?.timestamp_osm_base ?? '', buildings: [], roads: [], stations: [] }
  for (const el of d.elements) {
    const t = el.tags ?? {}
    if (el.type === 'node') { ctx.stations.push({ name: t['name:en'] ?? t.name ?? 'station', c: [el.lon, el.lat] }); continue }
    const g: LL[] = el.geometry.map(p => [p.lon, p.lat])
    if (t.building) ctx.buildings.push({ id: el.id, g, h: t.height, l: t['building:levels'], t: t.building, n: t['name:en'] ?? t.name })
    else ctx.roads.push({ id: el.id, g, k: t.highway, w: t.width, ln: t.lanes, n: t['name:en'] ?? t.name })
  }
  return ctx
}

/** Live OSM context around a point (used outside the bundled snapshot). Mirrors are raced; the first good answer wins. */
export const fetchContext = async ([lng, lat]: LL, r = 0.0035, timeoutMs = 45_000): Promise<Context> => {
  const [s, w, n, e] = [lat - r, lng - r, lat + r, lng + r].map(v => v.toFixed(5))
  const q = `[out:json][timeout:40];(way["building"](${s},${w},${n},${e});way["highway"~"^(motorway|trunk|primary|secondary|tertiary|unclassified|residential|service|living_street)$"](${s},${w},${n},${e});node["railway"="station"](${(lat - 0.01).toFixed(5)},${(lng - 0.01).toFixed(5)},${(lat + 0.01).toFixed(5)},${(lng + 0.01).toFixed(5)}););out tags geom;`
  const ctl = new AbortController()
  const timer = setTimeout(() => ctl.abort(), timeoutMs)
  try {
    const d = await Promise.any(OVERPASS.map(async url => {
      const res = await fetch(url, { method: 'POST', body: new URLSearchParams({ data: q }), signal: ctl.signal })
      if (!res.ok) throw new Error(`${url} ${res.status}`)
      return res.json()
    }))
    return parse(d, [+w, +s, +e, +n])
  } finally {
    clearTimeout(timer)
    ctl.abort()
  }
}

export const covers = (ctx: Context | null, at: LL) => !!ctx && inBox(at, [ctx.bbox[0] + 0.0015, ctx.bbox[1] + 0.0015, ctx.bbox[2] - 0.0015, ctx.bbox[3] - 0.0015])

/** Thai land units: 1 rai = 4 ngan = 400 sq wah = 1,600 m². */
export const rai = (m2: number) => {
  const wah = m2 / 4
  const r = Math.floor(wah / 400)
  const ng = Math.floor((wah - r * 400) / 100)
  return `${r}-${ng}-${(wah - r * 400 - ng * 100).toFixed(1)} rai`
}

