"""Copy session transcripts into transcripts/ with a colleague's name and the employer's name/emails redacted."""
import json, re, sys
from pathlib import Path

SRC = Path(r"C:\Users\amana\.claude\projects\d--OffCAMPUS-RECUITMENT-Assignment-1")
OUT = Path(__file__).resolve().parent.parent / "transcripts"
FILES = {"50971ef9-4d3a-4645-98dc-667d5c416655": "session-1-50971ef9", "12629d5f-1382-4f76-a2ef-58a07eda1f66": "session-2-12629d5f", "1ddfc9cf-2c1a-4c9b-acfc-1e4bb035e80b": "session-3-1ddfc9cf"}
SUBS = [(re.compile(r"[\w.%+-]+@[redacted]\.com", re.I), "[redacted-email]"), (re.compile(r"[redacted]\s*dct|[redacted]", re.I), "[redacted]"), (re.compile(r"[redacted]|[redacted]", re.I), "[redacted]")]

def clean(v):
    if isinstance(v, str):
        if len(v) > 2000 and " " not in v:  # base64 payloads (images)
            return v
        for p, r in SUBS:
            v = p.sub(r, v)
        return v
    if isinstance(v, list):
        return [clean(x) for x in v]
    if isinstance(v, dict):
        return {k: clean(x) for k, x in v.items()}
    return v

for sid, name in FILES.items():
    lines = [json.dumps(clean(json.loads(l)), ensure_ascii=False) for l in (SRC / f"{sid}.jsonl").read_text(encoding="utf8").splitlines() if l.strip()]
    text = "\n".join(lines) + "\n"
    left = [p.pattern for p, _ in SUBS if p.search(text)]
    (OUT / f"{name}.jsonl").write_text(text, encoding="utf8")
    print(name, len(lines), "lines", "LEFT: " + ", ".join(left) if left else "clean")
EOF
