"""Copy session transcripts into the repo, redacting a colleague's name and the employer's name/emails. Bytes otherwise untouched."""
import json, re
from pathlib import Path

SRC = Path(r"C:\Users\amana\.claude\projects\d--OffCAMPUS-RECUITMENT-Assignment-1")
OUT = Path(r"D:\OffCAMPUS_RECUITMENT\Assignment 1\transcripts")
FILES = {"50971ef9-4d3a-4645-98dc-667d5c416655": "session-1-50971ef9", "12629d5f-1382-4f76-a2ef-58a07eda1f66": "session-2-12629d5f", "1ddfc9cf-2c1a-4c9b-acfc-1e4bb035e80b": "session-3-1ddfc9cf"}
SUBS = [
    (re.compile(r"[redacted]\.[redacted]@[redacted]\.com|tech\.team1@[redacted]\.com", re.I), "[redacted-email]"),
    (re.compile(r"[redacted]\s*dct|[redacted]", re.I), "[redacted]"),
    (re.compile(r"[redacted]|[redacted]", re.I), "[redacted]"),
]

for sid, name in FILES.items():
    raw = (SRC / f"{sid}.jsonl").read_bytes().decode("utf8")
    for p, r in SUBS:
        raw = p.sub(r, raw)
    for line in raw.splitlines():
        if line.strip():
            json.loads(line)
    (OUT / f"{name}.jsonl").write_bytes(raw.encode("utf8"))
    print(name, "clean, valid JSON")

